import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"雷火豐","description":"周易折中 - 雷火豐","frontmatter":{"title":"雷火豐","description":"周易折中 - 雷火豐"},"headers":[],"relativePath":"classics/zhezhong/061.md","filePath":"classics/zhezhong/061.md"}'),h={name:"classics/zhezhong/061.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="雷火豐" tabindex="-1">雷火豐 <a class="header-anchor" href="#雷火豐" aria-label="Permalink to “雷火豐”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>〈豐序卦〉：得其所歸者必大，故受之以《豐》。物所歸聚必成莫大，故《歸妹》之後受之以《豐》也。《豐》，盛大之義。為卦震上離下，震動也，離明也。以明而動，動而能明，皆致豐之道。明足以照，動足以亨，然後能致豐大也。”</p><p>豐：亨，王假之，勿憂，宜日中。</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>豐，大也，以明而動，盛大之勢也。故其佔有亨道焉。然王者至此盛極當衰，則又有憂道焉。聖人以為徒憂無益，但能守常，不至於過盛，則可矣。故戒以勿憂，宜日中也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>豐為盛大，其義自亨。極天下之光大者，唯王者能至之。假，至也。天位之尊，四海之富，群生之眾，王道之大極，豐之道其唯王者乎？豐之時，人民之繁庶，事物之殷盛，治之豈易周，為可憂慮。宜如日中之盛明，廣照無所不及，然後無憂也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>張子曰：宜日中，不宜過中也。</p></li><li><p>郭氏忠孝曰：豐者，盛大之名。盛大所以亨，然物極盛大者，憂必將至。日過中則昃，豐過盛則衰。聖人慾持滿以中，故言宜日中。</p></li><li><p>項氏安世曰：豐卦皆以明為主，故下三爻皆明而無咎，上三爻皆暗，以能求明為吉，不能求為兇。此所以宜日中也。</p></li><li><p>胡氏炳文曰：豐之大有亨道焉，大則必通也，亦有憂道焉，大則可憂也。不必過於憂，如日之中，斯可矣。泰、晉、夬、家人、升皆曰“勿恤”，此曰“勿憂”，皆當極盛之時，常人所不憂而聖人所深憂。其辭曰“勿憂”，深切之辭，非謂無憂也。</p></li><li><p>何氏楷曰：豐有憂道焉，而云勿憂，蓋於此有道焉，可不必憂也。其道安在？亦曰致豐之本，即保豐之道。何以致豐？離明主之，而震動將之也。宜常如日之方中，使其明無所不及，則幽隱畢照，斯可永保夫豐亨矣。</p></li></ul><p>象曰：雷電皆至，豐。君子以折獄致刑</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>取其威照並行之象。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>雷電皆至，明震並行也。二體相合，故云皆至。明動相資成豐之象，離明也，照察之象；震動也，威斷之象。折獄者必照其情實，唯明克允；致刑者以威於奸惡，唯斷乃成。故君子觀雷電明動之象，以折獄致刑也。噬嗑言先王飭法，豐言君子折獄，以明在上而麗於威震，王者之事故為制刑立法；以明在下而麗於威震，君子之用故為折獄致刑。旅明在上而云君子者，旅取慎用刑與不留獄，君子皆當然也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰 ：斷決獄訟，須得虛實之情；致用刑罰，必得輕重之中。若動而不明，則淫濫斯及。故君子象於此卦而折獄致刑。</p></li><li><p>蘇氏軾曰 ：傳曰為刑罰威獄，以類天之震曜。故易至於雷電相遇，則必及刑獄，取其明以動也。至於離與艮相遇，曰“無折獄無留獄”，取其明以止也。</p></li><li><p>朱氏震曰 ：電明照也，所以折獄；雷威怒也，所以致刑。</p></li><li><p>朱子語類 ：問雷電噬嗑與雷電豐亦同，曰噬嗑明在上，是明得事理，先立這法，在此未有犯威人，留待異時之用，故云“明罰飭法”。豐威在上，明在下，是用這法時，須是明見下情曲折，方得，不然威動於上，必有過錯也，故云“折獄致刑”。</p></li></ul><p>彖曰：豐，大也；明以動，故豐</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>（以卦德、卦名義釋）</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>豐者，盛大之義。離明而震動，明動相資而成豐大也。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li>楊氏簡曰 ：以明而動，故豐，故亨。以昏而動，則反是矣。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>明以動，故豐。亦非正釋名義，乃推明其所以致豐之故，以起釋辭之端。與壯、萃同。以字與而字不同，而字有兩意，以字只是一意，重在首字。如“以剛而動”所以致壯，可見處壯者之必貞也；“以順而說”所以致聚，可見處萃者之必順也；“以明而動”所以致豐，可見處豐者之必明也。卦爻之義皆欲其明而防其昏，故傳先發此義，以示玩辭之要。</p><p>王假之，尚大也；勿憂，宜日中，宜照天下也</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>釋卦辭</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>王者有四海之廣、兆民之眾，極天下之大也。故豐大之道，唯王者能致之。所有既大，其保之、治之之道亦當大也。故王者之所尚，至大也。所有既廣、所治既眾，當憂慮其不能周及，宜如日中之盛明，普照天下無所不至，則可勿憂矣。如是然後能保其豐大。保有豐大，豈小才小知之所能也。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li>吳氏曰慎曰 ：所以宜日中者，恐日中則昃也。照天下，日中時昃，日中後。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>尚大謂王者至此所尚者大也。志意廣大，則不能謹小慮微，而明有所不照，即昏之徴而衰之兆也。故言宜日中者，謂能常明不昏，則能常中不昃。</p><p>日中則昃，月盈則食；天地盈虛，與時消息，而況於人乎？況於鬼神乎？</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>（此又闡明卦辭外意，言不可過中也）</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>既言豐盛之至，復言其難常以為誡也。日中盛極則當昃昳，月既盈滿則有虧缺。天地之盈虛尚與時消息，況人與鬼神乎？盈虛謂盛衰，消息謂進退。天地之運亦隨時進退也。鬼神謂造化之跡於萬物，盛衰可見其消息也。於豐盛之時而為此誡，欲其守中不至過盛，處豐之道豈易也哉。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎逹曰 ：先陳天地，後言人、鬼神者，欲以輕譬重，亦先尊後卑也。日月先天地者，承上“宜日中之文”，遂言其昃食，因舉日月以對，然後並陳天地。作文之體也。</p></li><li><p>朱子語類雲 ：豐卦彖許多言語，其實只在“日中則昃，月盈則食，天地盈虛，與時消息”數語上。這盛得極，常須謹謹保守得日中時候，方得。不然，便是偃仆傾壊了。 問 ：鬼神者，造化之跡。然天地盈虛即是造化之跡矣，而復言鬼神何耶？ 曰：天地舉全體而言，鬼神指其功用之跡，似有人所為者。</p></li><li><p>問 ：鬼神者，造化之跡。然天地盈虛即是造化之跡矣，而復言鬼神何耶？ 曰：天地舉全體而言，鬼神指其功用之跡，似有人所為者。</p></li><li><p>毛氏璞曰 ：豐大也，亦盈也。惟有道者明德若不足，未嘗中故不昃，未嘗盈故不食。日新則為大，反是則為盈。知日中之宜，則知日昃之可戒。</p></li><li><p>林氏希元曰 ：卦辭“勿憂，宜日中”，所以然處未之及此方言之，以補卦辭之所未及。故曰“發明卦辭外意”，言卦外之意也。雖曰辭外之意，然實有此意，但辭不及耳。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>林氏之說得之。朱子釋彖辭亦曰：盛極當衰也。</p><p>初九：遇其配主，雖旬無咎，往有尚。</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>配主，謂四。旬，均也，謂皆陽也。當豐之時，明動相資，故初九之遇九四，雖皆陽剛，而其佔如此也。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>雷電皆至，成豐之象。明動相資，致豐之道。非明無以照，非動無以行，相須猶形影相資，猶表裡。初九明之初，九四動之初，宜相須以成其用。故雖旬而相應，位則相應用則相資。故初謂四為配主，已所配也。配雖匹稱，然就之者也，如配天以配君子。故初於四雲“配”，四於初雲“夷”也。雖旬無咎，旬均也。天下之相應者，常非均敵，如陰之應陽，柔之從剛，下之附上。敵則安肯相從？唯豐之初四，其用則相資，其應則相成，故雖均是陽剛，相從而無過咎也。蓋非明則動無所之，非動則明無所用，相資而成用。同舟則胡越一心，共難則仇怨恊力，事勢使然也。往而相從，則能成其豐，故云有尚，有可嘉尚也。在它卦則不相下而離隙矣。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>胡氏瑗曰：旬者，十日也，謂數之盈滿也。言初與四其徳相符，雖居盈滿盛大之時，可以無咎。以此而往，則行有所尚也。</p></li><li><p>蘇氏軾曰：凡人知生於憂患而愚生於安佚。豐之患常在於暗，故爻皆以明暗為吉凶也。初九、六二、九三三者皆離也，而有明徳者也。九四、六五、上六則所謂豐而暗者也。離，火也，日也，以下升上，其性也以明發暗，其徳也。故三離皆上適於震，初九適四，其配之所在也，故曰配主。</p></li><li><p>項氏安世曰：初以四為配，四以初為夷，上下異辭也。自下並上曰配。</p></li><li><p>胡氏炳文曰：初不言豐，初未至豐也。五亦不言豐者，陰虛歡然，方賴在下之助，不知有其豐也。凡卦爻取剛柔相應，豐則取明動相資。初之剛與四之剛同徳而相遇，雖兩陽之勢均敵，往而從之，非特無咎，且有尚矣。或曰十日為旬。</p></li><li><p>來氏知徳曰：因“宜日中”句，爻辭皆以日言。文王象豐以一日象之，故曰“勿憂，宜日中”。周公象豐以十日象之，故曰“雖旬無咎”。十日為旬，言初之豐以一月論已，一旬也正豐之時也。</p></li></ul><p>象曰：雖旬無咎，過旬災也</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>戒佔者不可求勝其配，亦爻辭外意。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>聖人因時而處宜，隨事而順理。夫勢均則不相下者，常理也。然有雖敵而相資者，則相求也，初四是也。所以雖旬而無咎也。與人同而力均者，在乎降已以相求，協力以從事。若懷先已之私，有加上之意，則患當至矣。故曰過旬災也。均而先已是過旬也，一求勝則不能同矣。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>劉氏牧曰 ：旬數之極也，猶日之中也。言無咎者，謂初未至中，猶可進也；若進而過中，則災，故象稱“過旬災”也。爻辭不言豐者，謂初未至豐也。</p></li><li><p>胡氏瑗曰 ：言雖居豐盈之時，可以無咎；若過於盈滿，則必有傾覆之災也。</p></li><li><p>俞氏琰曰 ：爻辭雲“雖旬無咎”，爻傳雲“過旬災”，則戒其不可過也。蓋與彖傳“天地日月”說同。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>過旬災即日中則昃，月盈則食之意也。經意謂同德相濟，雖當盈滿之時可以無咎，況初居豐之始，未及日中乎？傳意則謂正宜及今而圖之，耳稍過於中，便將有災矣。其義相備也。</p><p>六二：豐其蔀，日中見鬥，往得疑疾，有孚發若，吉。</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>六二居豐之時，為離之主，至明者也。而上應六五之柔暗，故為豐蔀見鬥之象。蔀，障蔽也，大其障蔽，故日中而昏也。往而從之，則昏暗之主必反見疑。唯在積其誠意以感發之，則吉。戒佔者宜如是也。虛中有孚之象。</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>明動相資，乃能成豐。二為明之主，又得中正，可謂明者也。而五在正應之地，陰柔不正，非能動者。二五雖皆陰，而在明動相資之時，居相應之地，五才不足，既其應之才不足資，則獨明不能成豐。既不能成豐，則喪其明功，故為豐其蔀，日中見鬥。二至明之才，以所應不足與而不能成其豐，喪其明功，無明功則為昏暗，故云見鬥。鬥昏見者也。蔀，周匝之義，用障蔽之物掩晦於明者也。鬥屬陰而主運平，象五以陰柔而當君位，日中盛明之時乃見鬥，猶豐大之時乃遇柔弱之主。鬥以昏見，言見鬥，則是明喪而暗矣。二雖至明中正之才，所遇乃柔暗不正之君，既不能下求於己，若往求之，則反得疑猜忌疾。暗主如是也。然則如之何而可？夫君子之事上也，不得其心，則盡其至誠以感發其志意而已。苟誠意能動，則雖昏蒙可開也，雖柔弱可輔也，雖不正可正也。古人之事庸君常主而克行其道者，已之誠意上逹而君見信之篤耳。管仲之相桓公，孔明之輔後主是也。若能以誠信發其志意，則得行其道，乃為吉也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>服氏䖍曰：日中而昏也。</p></li><li><p>張子曰：凡言往者，皆進而之上也。初進而上，則遇陽而有尚；二既以陰居陰，又所應亦陰，故往増疑疾。</p></li><li><p>郭氏雍曰：六二為離明之中，而有豐蔀之暗者，以陰居陰上，非正應，所以有從暗之象也。天下之理，明則無疑，暗則疑。六二用明投暗，往得疑疾，乃其宜也。然任其中正，有孚而發，則動無不吉。</p></li><li><p>徐氏㡬曰：卦言“宜日中”，以下體言之，則二為中；以一卦言之，則三四為中。故二三四皆言日中。剛生明，故初應四，則為往有尚；柔生暗，故二應五，為往得疑疾也。</p></li></ul><p>象曰：有孚發若，信以發志也</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>有孚發若，謂以已之孚信感發上之心志也。苟能發，則其吉可知，雖柔暗有可發之道也。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>趙氏汝梅曰 ：疾得於境之疑，孚發於志之信。</p></li><li><p>王氏申子曰 ：二虛中故有孚，五亦虛中故可發言，以誠相感也。</p></li></ul><p>九三：豐其沛，日中見沬，折其右肱，無咎。</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>沛，一作斾，謂幡幔也。其蔽甚於蔀矣。沬，小星也。三處明極而應上六，雖不可用，而非咎也。故其象佔如此。</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>沛字，古本有作斾字者。王弼以為幡幔，則是斾也。幡幔圍蔽於內者，豐其沛，其暗更甚於蔀也。三明體而反暗於四者，所應陰暗故也。三居明體之上，陽剛得正，本能明者也。豐之道必明動相資而成，三應於上六，上陰柔又無位而處震之終，既終則止矣，不能動者也。它卦至終則極，震至終則止矣。三無上之應，則不能成豐。沫星之微小無名數者，見沫暗之甚也。豐之時而遇上六，日中而見沫者也。右肱人之所用，乃折矣，其無能為可知。賢智之才遇明君，則能有為於天下；上無可賴之主，則不能有為，如人之折其右肱也。人之為有所失，則有所歸咎，曰“由是故致是”。若欲動而無右肱，欲為而上無所賴，則不能而已，更復何言，無所歸咎也。</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><ul><li>九三之蔽又甚於二四者。爻取日中為昏義，二三四在一卦之中，而九三又在三爻之中也。且二應五，為柔中之主；四應初，為同徳之助；三所應者，乃過中處極之陰，其蔽安得不甚哉？上六以其昏昏，使人昏昏。故九三雖以剛明之才為之股肱，而不免於毀折。然於義為無咎者，守其剛正以事上，反己無怍而眾無尤也。</li></ul><p>九三之蔽又甚於二四者。爻取日中為昏義，二三四在一卦之中，而九三又在三爻之中也。且二應五，為柔中之主；四應初，為同徳之助；三所應者，乃過中處極之陰，其蔽安得不甚哉？上六以其昏昏，使人昏昏。故九三雖以剛明之才為之股肱，而不免於毀折。然於義為無咎者，守其剛正以事上，反己無怍而眾無尤也。</p><ul><li>易中所取者雖虛象，然必天地閒有此實事，非憑虛造設也。日中見鬥，甚而至於見沬，所取喻者固謂至昏伏於至明之中。然以實象求之，則如太陽食時是也。食限多則大星見，食限甚則小星亦見矣。所以然者，陰氣蔽障之故。故所謂“豐其蔀”，“豐其沛”者，乃蔽日之物，非蔽人之物也。且此義亦與彖傳“日中則昃，月盈則食”相發。</li></ul><p>易中所取者雖虛象，然必天地閒有此實事，非憑虛造設也。日中見鬥，甚而至於見沬，所取喻者固謂至昏伏於至明之中。然以實象求之，則如太陽食時是也。食限多則大星見，食限甚則小星亦見矣。所以然者，陰氣蔽障之故。故所謂“豐其蔀”，“豐其沛”者，乃蔽日之物，非蔽人之物也。且此義亦與彖傳“日中則昃，月盈則食”相發。</p><p>象曰：豐其沛，不可大事也；折其右肱，終不可用也</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>三應於上，上應而無位，陰柔無勢力而處既終，其可共濟大事乎？既無所賴，如右肱之折，終不可用矣。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li>潘氏士藻曰 ：六二雖當豐蔀之時，然五得位得中，猶可以大事，故六二發若之孚可施也。九三所應上六，無可發之明矣，不可用而不用，保身之哲也。</li></ul><p>九四：豐其蔀，日中見鬥，遇其夷主，吉。</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>象與六二同。夷，等夷也，謂初九也。其佔為當豐而遇暗主，下就同徳則吉也。</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>四雖陽剛，為動之主，又得大臣之位，然以不中正，遇陰暗柔弱之主，豈能致豐大也？故為豐其蔀。蔀，周圍掩蔽之物，周圍則不大，掩蔽則不明。日中見鬥，當盛明之時反昏暗也。夷主，其等夷也，相應故謂之主。初四皆陽而居初，是其同徳，又居相應之地，故為夷主。居大臣之位，而得在下之賢同徳相輔，其助豈小也哉？故吉也。如四之才，得在下之賢為之助，則能致豐大乎？曰：在下者上有當位為之與，在上者下有賢才為之助，豈無益乎？故吉也。然而致天下之豐，有君而後能也。五陰柔居尊，而震體無虛中巽順下賢之象，下雖多賢，亦將何為？蓋非陽剛中正，不能致天下之豐也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰：據初適四，則以四為主，故曰“遇其配主”。自四之初，則以初為主，故曰“遇其夷主”也。</p></li><li><p>張子曰：近比於五，故亦云“見鬥”。正應亦陽，故云“夷主”。</p></li><li><p>郭氏雍曰：二之豐蔀見鬥，以重陰而非正應也，而有孚發若吉者，中正也。四之豐蔀見鬥，非中正也，而遇其夷主吉，者應初而有遇也。二爻之義相類，故其辭同而皆終之以吉。有為之時，明動必相濟然後有成，故初謂四為配主，四謂初為夷主。迭稱主者，明動相須，莫適為主。惟明者知求動以為主，動者知求明以為主，故也。</p></li><li><p>鄭氏汝諧曰：初視四為配，以下偶上也；四視初為夷，降上就下也。</p></li></ul><p>象曰：豐其蔀，位不當也；日中見鬥，幽不明也；遇其夷主，吉行也</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>位不當，謂以不中正居高位，所以暗而不能致豐。日中見鬥，幽不明也，謂幽暗不能光明。君陰柔而臣不中正，故也。遇其夷主吉行也，陽剛相遇，吉之行也。下就於初，故云行，下求則為吉也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>項氏安世曰 ：六二指六五為蔀為鬥，故往則入於暗而得疑；九四之蔀與鬥皆自指也，故行則遇明而得吉。</p></li><li><p>吳氏澄曰 ：豐蔀見鬥，六二爻辭已備，象傳不釋而獨九四致其詳者，蓋二象由九四而成，四為蔀，故二見鬥；二爻之象同而所重在四也。</p></li></ul><p>六五：來章有慶譽，吉。</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>質雖柔暗，若能來致天下之明，則有慶譽而吉矣。蓋因其柔暗而設此以開之，佔者能如是，則如其佔矣。</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>五以陰柔之才為豐之主，固不能成其豐大。若能來致在下章美之才而用之，則有福慶，復得美譽，所謂吉也。六二文明中正，章美之才也。為五者誠能致之，在位而委任之，可以致豐大之慶，名譽之美，故吉也。章美之才主二而言，然初與三四皆陽剛之才，五能用賢，則彚徵矣。二雖陰，有文明中正之徳，大賢之在下者也。五與二雖非陰陽正應，在明動相資之時，有相為用之義。五若能來章，則有慶譽而吉也。然六五無虛已下賢之義，聖人設此義以為教耳。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>馮氏當可曰：六二言“往”，六五言“來”，往來交合，章明之象。</p></li><li><p>項氏安世曰：六二以五為蔀，在上而暗也；六五以二為章，在下而明也。</p></li><li><p>陳氏曰：五陰暗則往而疑，二文明則來而章。章者，離體文明之象。</p></li><li><p>胡氏炳文曰：三爻稱“日中”，皆有所蔽；六五不稱“日中”，蓋宜日中無蔽也。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>五，君位也。彖辭所謂“王假之者”，即此位。則五乃卦主也。卦義所重在明以照天下，六五雖非明體，然下應六二為文明之主，而五有柔中之徳，能資其章明以自助，則卦義所謂“勿憂，宜日中”者，實與此爻義合。</p><p>象曰：六五之吉，有慶也</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>其所謂吉者，可以有慶福及於天下也。人君雖柔暗，若能用賢才，則可以為天下之福，唯患不能耳。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li>何氏楷曰 ：人君以天下常豐為慶，慶以天下故，吉言慶則譽在其中矣。</li></ul><p>上六：豐其屋，蔀其家，窺其戸，闃其無人，三歲不覿，兇。</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>以陰柔居豐極，處動終，明極而反暗者也。故為豐大其屋而反以自蔽之象。無人不覿，亦言障蔽之深，其兇甚矣。</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>六以陰柔之質而居豐之極，處動之終，其滿假躁動甚矣。處豐大之時，宜乎謙屈而處，極高致豐大之功，在乎剛健而體陰柔。當豐大之任，在乎得時而不當位，如上六者，處無一當，其兇可知。豐其屋，處太高也；蔀其家，居不明也。以陰柔居豐大而在無位之地，乃高亢昏暗，自絕於人，人誰與之？故窺其戸，闃其無人也。至於三歲之久而不知變，其兇宜矣。不覿，謂尚不見人，蓋不變也。六居卦終，有變之義而不能遷，是其才不能也。</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>龔氏煥曰：豐卦與明夷相似，唯變九四一爻。豐其蔀蔽，皆六五、上六二陰所為。二豐其蔀，以五為應也；三豐其沛，以上為應也；四豐其蔀，以承五也。然五雖柔暗，以其得中，故有來章之吉；上居豐極，始則蔽人之明，終以自蔽，與明夷上六相似。</p></li><li><p>何氏楷曰：處豐之極，亢然自高，豐大其居。以明得意，方且深居簡出，距人於千里之外，豈知兇將及矣？能無懼乎？</p></li></ul><h3 id="總論" tabindex="-1">總論 <a class="header-anchor" href="#總論" aria-label="Permalink to “總論”">​</a></h3><ul><li>熊氐良輔曰：豐六爻以不應為善。初四皆陽，初曰“遇其配主”，四曰“遇其夷主”；二五皆陰，二曰“有孚發若吉”，五曰“來章有慶譽吉”。三與上為正應，三不免於折肱，而上則甚兇。當豐大之時，以同徳相輔為善，不取陰陽之應也。</li></ul><p>象曰：豐其屋，天際翔也；窺其戸，闃其無人，自藏也</p><h3 id="本義-12" tabindex="-1">本義 <a class="header-anchor" href="#本義-12" aria-label="Permalink to “本義”">​</a></h3><p>藏謂障蔽。</p><h3 id="程傳-17" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-17" aria-label="Permalink to “程傳”">​</a></h3><p>六處豐大之極，在上而自高，若飛翔於天際，謂其高大之甚。窺其戶而無人者，雖居豐大之極而實無位之地，人以其昏暗自高大，故皆棄絕之，自藏避而弗與親也。</p><h3 id="集說-15" tabindex="-1">集說 <a class="header-anchor" href="#集說-15" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>石氏介曰 ：始顯大終自藏，皆聖人戒其過盛。子云曰：“炎炎者滅，隆隆者絕。”觀雷觀火，為盈為實，天收其聲，地藏其熱。高明之家，鬼瞰其室，正合此義。</p></li><li><p>張子曰 ：豐屋蔀家，自蔽之甚，窮大而失居者也。處上之極不交於下，而居動之末，故曰天際翔也。</p></li><li><p>朱子語類雲 ：豐其屋，天際翔也，似說如翬斯飛様，言其屋高大到於天際，卻只是自蔽障得闊。</p></li></ul>',129)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
